python3 - <<'EOF'
from PIL import Image
im = Image.open('r154-search-light.png').convert('RGB')
w,h = im.size
d = im.get_flattened_data() if hasattr(im,'get_flattened_data') else None
px = im.load()
# scan for dark pixels in region x700..1100, y28..120
rows={}
for y in range(28,120):
    xs=[x for x in range(700,1100) if sum(px[x,y])<200]
    if xs: rows[y]=(min(xs),max(xs),len(xs))
for y in sorted(rows)[:40]: print(y, rows[y])
EOF

